            "name": "ความหวังใหม่",
            "sections": {
                "1": "ตามคำสั่งของเจ้าปีศาจ คุณมุ่งหน้าเข้าสู่ บึงค้าง เพื่อทำลายร่องรอยสุดท้ายของการต่อต้านการปกครองของปีศาจ คุณบดขยี้โทเท็มอันสุดท้ายและรองเท้าบู๊ตของคุณจมกลับลงในโคลน คุณเดินไปหายามที่บาดเจ็บสาหัส “ข้าจะบอกเจ้า” เขาหอบ “แต่เพียงเพราะข้ารู้ว่าเจ้าไม่ได้ชั่วร้ายจริงๆ แทนที่จะตามล่าพวกเรา 49 จงสู้ร่วมกับเรา 50 ช่วยเรายึดเมืองคืนจากปีศาจเหล่านั้น มุ่งหน้าไปทางตะวันออก ไปที่ชายแดนเทือกเขาวอตเชอร์ มองไปทางเหนือของป่าต้นแอช คุยกับผู้บัญชาการ ช่วยปลดปล่อยเมือง...” คำพูดของยามที่กำลังจะตายอาจมีความจริงอยู่บ้าง ไปช่วยพวกกบฏกันเถอะ!",
                "2": "พวกกบฏโง่เหล่านั้นไม่สมควรได้รับความช่วยเหลือจากคุณ คุณช่วยให้ กลูมฮาเวน กำจัดปีศาจ และให้เจ้าผู้ปกครองอื่นมาแทนที่",
                "3": "พวกกบฏโง่เหล่านั้นไม่สมควรได้รับความช่วยเหลือจากคุณ ทิศทางของยามพิสูจน์ว่ามีประโยชน์ในการสังหารกบฏทุกคนจนหมด",
                "4": "คุณตามทิศทางของยามที่ตายแล้วเข้าสู่เชิงเขาของเทือกเขาวอตเชอร์ ไม่ใช่เพื่อฆ่าและทำลาย แต่เพื่อช่วยเหลือ ตอนแรกพวกกบฏดูระแวง แต่ในที่สุดก็เปิดใจ “พูดตามตรง” กัปตันกบฏกล่าว “เราต้องการความช่วยเหลือจากเจ้าอย่างยิ่ง เราใช้ทรัพยากรทั้งหมดสร้างปืนใหญ่ที่เจาะกำแพง กลูมฮาเวน ได้ แต่เมื่อทำสำเร็จแล้ว เราไม่มีกำลังคนและอาวุธเพียงพอที่จะเข้าปะทะกองกำลังปีศาจและขับไล่พวกมันออกจากบ้านของเรา” กัปตันคลี่แผนที่เมืองบนโต๊ะ “แต่เจ้าอาจเป็นอาวุธลับของเรา สามวันต่อมา เมื่อพวกกบฏนำปืนใหญ่เข้าที่ได้ คุณลอบเข้าไปใน ป้อมปราการผี เตรียมยึดคลังอาวุธ คุณตัดสินใจว่าการโจมตีสองทางเป็นวิธีที่ดีที่สุดที่จะได้คลังอาวุธอย่างรวดเร็ว คุณได้ยินเสียงระเบิดของปืนใหญ่จากที่ไกลและลงมือทันที คุณยึดคลังอาวุธชุดสุดท้ายได้ทันทีที่นักรบกบฏบุกเข้าสู่ป้อม การกวาดล้างปีศาจออกจากส่วนที่เหลือของอาคารกลายเป็นเรื่องง่ายหลังจากนั้น ด้วยที่มั่นอันแข็งแกร่งในเมืองและประชาชนอยู่ข้างคุณ กระแสก็พลิกต่อต้านปีศาจอย่างรวดเร็ว การต่อสู้ยังคงยาวนานและยากลำบาก เมื่อกองกำลังเพิ่มเติมยังคงมาจากมิติธาตุ แต่ท้ายที่สุดมันเพียงทำให้ชาว กลูมฮาเวน สามัคคีกันแน่นแฟ้นขึ้น ต่อสู้กับศัตรูร่วม และเมื่อคุณไม่ต่อสู้เพื่อพวกมันอีกต่อไป กองกำลังปีศาจก็ยอมถอยกลับสู่มิติของตัวเองในที่สุด สัปดาห์ต่อมายากลำบาก เมื่อประชาชนสร้างกำแพงและทุกอย่างที่ถูกทำลายในการต่อสู้ยืดเยื้อขึ้นใหม่ พวกเขายังต้องใช้เวลาในการไว้ใจคุณอีกครั้งหลังการทรยศที่ไตร่ตรองมาไม่ดี แต่ กลูมฮาเวน ก็ฟื้นตัวได้ตามเวลา เต็มไปด้วยผู้คนที่ยืดหยุ่น และท่าเรือก็สำคัญต่อการค้า หลังจากนั้นมันไม่เคยรู้สึกเหมือนเดิมเลย แต่ในบางจุด อย่างน้อยมันก็ยังรู้สึกเหมือนบ้าน"
            },
