                "1": "ขณะที่คุณเดินผ่าน ตลาดใหม่ แคสแซนดรา สังเกตว่ามีบางอย่างผิดปกติรอบตัวคุณ ทุกอย่างเงียบเกินไป และเธอสงสัยว่ากับดักกำลังจะสปริงใส่คุณ ไม่นาน สิ่งมีชีวิตประหลาดก็โผล่ออกมาจากเงา นำโดย อีสเธอร์ ร่างยักษ์ถือมีดเปลวไฟ แคสแซนดรา เผยว่ามันคือ ฮัสก์ เปลือกที่ถูกความเสื่อมกัดกินของสิ่งที่เคยเป็น อีสเธอร์ บางทีครั้งนี้การหนีอาจเป็นทางเลือกที่เป็นไปได้",
                "2": "คุณพุ่งเข้าสู่ทางเข้า ตลาดใหม่ โดย ฮัสก์ ยังตามมา ยามสวมเกราะและเตรียมรบ แต่ ฮัสก์ เริ่มหัวเราะ บอกว่าการต่อสู้นี้เพียงถูกเลื่อนออกไป และไม่ช้าก็เร็วมันจะฆ่าคุณ แล้วมันก็หายไปในควันดำ",
                "3": "ในที่สุด ฮัสก์ ก็ล้มลง ครั้งนี้ ด้วยเสียงกระซิบสุดท้าย มันพูดถึงแผนการใหญ่ของความเสื่อมที่ดูเหมือนว่าคุณไม่ควรหยุดได้ ด้วยการถอนหายใจโล่งอก การต่อสู้นี้จบแล้ว แม้สงครามจะอีกไกลกว่านั้น แคสแซนดรา วาดรูนสีดำในอากาศ และนิมิตก็ค้างอยู่ตรงหน้าเธอ เธอเห็นแผนอื่นๆ กำลังดำเนินอยู่ แต่คุณจะหยุดมัน"
