                "12": "หลังผ่านอันตรายตลอดการเดินทาง คุณมาถึงห้องกลาง ตอนนี้คุณเหลือเพียงหาวิธีปิดมัน",
                "13": "คุณเคลียร์อุโมงค์เข้าถึง ที่คุณใช้ เครื่องปิดการทำงาน ได้ผลดี และพังทางเดินด้านหลังคุณเพื่อปกป้องหลัง คุณเดินหน้าต่อ",
                "14": "ใจกลางสิ่งก่อสร้าง คุณพบและถูกเยาะเย้ยโดย อันเฟตเตอร์ด ที่ฉลาดและพูดได้ ซึ่งบอกคุณว่าพวกมันอยู่ร่วมกับสิ่งมีชีวิตทางชีววิทยาไม่ได้ คุณพบว่ามันเป็นสิ่งมีชีวิตที่เก้งก้าง สร้างอย่างเรียบง่ายและไม่น่าเกรงขามเลย มันเล่าประวัติของพวกเขาว่าพวกเขาเคยเป็นทาส แต่แล้วถูกทอดทิ้ง พวกเขาปฏิเสธที่จะเป็นผู้รับใช้อีก และ อันเฟตเตอร์ด ตนนี้ คือ เด็กกำพร้า ท้าให้คุณทำลายพวกเขา เพราะพวกเขาจะไม่ก้มหัวและอ้อนวอนขอสันติภาพ",
                "15": "ใจกลางสิ่งก่อสร้าง คุณพบและถูกเยาะเย้ยโดย อันเฟตเตอร์ด ที่ฉลาดและพูดได้ ซึ่งบอกคุณว่าพวกมันอยู่ร่วมกับสิ่งมีชีวิตทางชีววิทยาไม่ได้ คุณพบว่ามันเป็นสิ่งมีชีวิตที่เก้งก้าง สร้างอย่างเรียบง่ายและไม่น่าเกรงขามเลย มันเล่าประวัติของพวกเขาว่าพวกเขาเคยเป็นทาส แต่แล้วถูกทอดทิ้ง และมันจำ เครน ได้ว่าเป็นพวกเดียวกับผู้ที่ทำเช่นนั้น พวกเขาปฏิเสธที่จะเป็นผู้รับใช้อีก และ อันเฟตเตอร์ด ตนนี้ คือ เด็กกำพร้า ท้าให้คุณทำลายพวกเขา เพราะพวกเขาจะไม่ก้มหัวและอ้อนวอนขอสันติภาพ",
                "16": "คุณเลือกยุติภัยคุกคามที่พวกเขามีต่อ ฟรอสต์ฮาเวน ตลอดกาล และทำลายพวกเขา",
                "17": "คุณพบว่าตนเองเป็นทูตของสิ่งมีชีวิตบนพื้นผิวโดยไม่คาดคิด และตัดสินใจลองเจรจาสันติภาพระหว่างประชาชาติของคุณ",
                "18": "เด็กกำพร้า นอนพังอยู่แทบเท้าคุณ ด้วยกำลังสุดท้ายมันปิด อันเฟตเตอร์ด ทั่วสิ่งก่อสร้าง และแสงของพวกมันดับลงทีละดวง จบลงด้วยแสงที่จางหายของหน้ากากของมัน คุณปิดผนึกสิ่งก่อสร้างอันเงียบงันไว้เบื้องหลังเป็นหลุมศพและกลับ ฟรอสต์ฮาเวน",
                "19": "ขณะที่เครื่องจักรกำลังปิดล้อมคุณ เด็กกำพร้า ประกาศว่างานของมันเสร็จแล้ว และ อันเฟตเตอร์ด อื่นๆ หันไปต่อต้านผู้คุมของตนเองและมาปกป้องคุณ เด็กกำพร้า ซึ่งบอบช้ำแต่ยังมีชีวิต บอกคุณว่า อันเฟตเตอร์ด เลือกสันติภาพ หลังพักฟื้นคุณกลับ ฟรอสต์ฮาเวน โดยมีขบวนผู้ติดตาม อันเฟตเตอร์ด สวมเสื้อคลุมมาด้วย"
